import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import classList from 'flarum/common/utils/classList';
import EditCustomTabItemModal from './EditCustomTabItemModal';
export default class MobileTabItem extends Component {
  view() {
    const {
      item
    } = this.attrs;
    const source = item.source ?? 'extension';
    return m(Button, {
      className: classList('Button', {
        'Button--dashed': source !== 'user'
      }, 'MobileTab-item', {
        'MobileTab-item--editable': source === 'user'
      }),
      icon: item.icon,
      onclick: () => {
        if (item.source !== 'user') return;
        const id = item.itemName.match(/(\d+)$/);
        if (!id) return;
        app.modal.show(EditCustomTabItemModal, {
          model: app.store.getById('custom-tab-items', id[0])
        });
      }
    }, item.label);
  }
}
flarum.reg.add('acpl-mobile-tab', 'admin/components/MobileTabItem', MobileTabItem);