import app from 'flarum/admin/app';
import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import FormSection from 'flarum/admin/components/FormSection';
import FormSectionGroup from 'flarum/admin/components/FormSectionGroup';
import Button from 'flarum/common/components/Button';
import MobileTabItemsRegistryAdmin from '../data/MobileTabItemsRegistryAdmin';
import EditCustomTabItemModal from './EditCustomTabItemModal';
import MobileTabVariantSettings from './MobileTabVariantSettings';
import MobileTabItem from './MobileTabItem';
export default class MobileTabSettingsPage extends ExtensionPage {
  /**
   * Sortablejs directly manipulates the DOM, which can confuse Mithril's diffing.
   * Changing this key forces a full re-render of the list, ensuring a clean sync.
   */
  forcedRefreshKey = 0;
  oninit(vnode) {
    super.oninit(vnode);
    this.loading = true;
    Promise.all([app.store.find('mobile-tab-variants'),
    //
    app.store.find('custom-tab-items')]).then(() => {
      this.loading = false;
      m.redraw();
    });
  }
  sections(vnode) {
    const items = super.sections(vnode);
    items.add('items', this.items(), 30);
    return items;
  }
  items() {
    return m("div", {
      className: "ExtensionPage-settings"
    }, m("div", {
      className: "container",
      key: this.forcedRefreshKey
    }, m(FormSectionGroup, null, this.variantsContent(), this.availableItemsContent())));
  }
  availableItemsContent() {
    return m(FormSection, {
      className: "MobileTabAvailableItems",
      label: app.translator.trans('acpl-mobile-tab.admin.available_items')
    }, m("p", {
      className: "helpText"
    }, app.translator.trans('acpl-mobile-tab.admin.available_items_help')), m("ul", {
      className: "MobileTabAvailableItems-list MobileTab-items",
      oncreate: this.createAvailableItemsSortable.bind(this),
      onremove: () => this.sortableAvailableItems?.destroy()
    }, this.availableItems().toArray().map(item => m("li", {
      className: `item-${item.itemName}`,
      key: item.itemName,
      "data-id": item.itemName
    }, m(MobileTabItem, {
      item: item
    })))), m(Button, {
      className: "Button",
      icon: "fas fa-plus",
      onclick: () => app.modal.show(EditCustomTabItemModal)
    }, app.translator.trans('acpl-mobile-tab.admin.create_new_item_button')));
  }
  variantsContent() {
    return m(FormSection, {
      className: "MobileTabVariants",
      label: app.translator.trans('acpl-mobile-tab.admin.variants.heading')
    }, m("p", {
      className: "helpText"
    }, app.translator.trans('acpl-mobile-tab.admin.variants.help')), m("ul", {
      className: "MobileTabVariants-list",
      oncreate: this.createVariantsSortable.bind(this),
      onremove: () => this.sortableVariants?.destroy()
    }, [...app.store.all('mobile-tab-variants')].sort((a, b) => a.position() - b.position()).map((variant, index) => m(MobileTabVariantSettings, {
      key: variant.id(),
      variant: variant,
      index: index,
      onSortEnd: this.refreshLists.bind(this)
    }))), m(Button, {
      className: "Button MobileTabVariants-add",
      icon: "fas fa-plus",
      onclick: this.createVariant.bind(this)
    }, app.translator.trans('acpl-mobile-tab.admin.variants.create')));
  }
  async createVariant() {
    const variant = app.store.createRecord('mobile-tab-variants');
    await variant.save({});
    m.redraw();
  }
  availableItems() {
    return new MobileTabItemsRegistryAdmin().items();
  }
  refreshLists() {
    this.forcedRefreshKey++;
    m.redraw();
  }
  async createAvailableItemsSortable(vnode) {
    const {
      default: sortableModule
    } = await flarum.reg.asyncModuleImport('flarum/admin/utils/loadSortable');
    this.sortableAvailableItems = sortableModule.create(vnode.dom, {
      group: {
        name: 'mobile-tab-items',
        pull: 'clone',
        put: true
      },
      animation: 150,
      sort: false,
      onEnd: this.refreshLists.bind(this)
    });
  }
  async createVariantsSortable(vnode) {
    const {
      default: sortableModule
    } = await flarum.reg.asyncModuleImport('flarum/admin/utils/loadSortable');
    this.sortableVariants = sortableModule.create(vnode.dom, {
      animation: 150,
      handle: '.MobileTabVariant-handle',
      draggable: '.MobileTabVariant',
      onEnd: this.refreshLists.bind(this),
      onUpdate: event => {
        if (event.oldIndex == null || event.newIndex == null) return;
        if (event.oldIndex === event.newIndex) return;
        const variants = [...app.store.all('mobile-tab-variants')].sort((a, b) => a.position() - b.position());
        const [moved] = variants.splice(event.oldIndex, 1);
        variants.splice(event.newIndex, 0, moved);
        variants.forEach((variant, position) => {
          variant.pushAttributes({
            position
          });
        });
        void app.request({
          method: 'POST',
          url: `${app.forum.attribute('apiUrl')}/mobile-tab-variants/order`,
          body: {
            order: variants.map(variant => variant.id())
          }
        });
        m.redraw();
      }
    });
  }
}
flarum.reg.add('acpl-mobile-tab', 'admin/components/MobileTabSettingsPage', MobileTabSettingsPage);