import Model from 'flarum/common/Model';
export default class MobileTabVariant extends Model {
  items = (() => Model.attribute('items', items => items.filter(item => item !== null)))();
  is_enabled = (() => Model.attribute('is_enabled'))();
  position = (() => Model.attribute('position'))();
  viewPermission() {
    return `acpl-mobile-tab.variant${this.id()}.view`;
  }
}
flarum.reg.add('acpl-mobile-tab', 'common/models/MobileTabVariant', MobileTabVariant);